// Primary page resolver
export function getPageData(hashPath) {
  const clean = hashPath.replace(/^#\/?/, '').replace(/^\//, '');
  const [a, b] = clean.split('/');

  let res;
  if (a === 'country' && b) {
    res = country(b);
  } else if (a === 'blog' && b) {
    res = post(b);
  } else if (P[a]) {
    res = P[a]();
  } else {
    res = P['']();
  }
  return res;
}

// Exact enhance implementation from original HTML
export function enhance(app) {
  if (!app) return;
  app.style.animation = 'none';
  void app.offsetWidth;
  app.style.animation = '';

  const ok = 'IntersectionObserver' in window && !window.matchMedia('(prefers-reduced-motion:reduce)').matches;

  const io = ok ? new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('in');
        setTimeout(() => {
          if (entry.target) entry.target.style.transitionDelay = '';
        }, 900);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.01, rootMargin: '150px' }) : null;

  app.querySelectorAll('.c, h2, details, .gal figure').forEach((el, idx) => {
    el.classList.add('rv');
    if (io) {
      el.style.transitionDelay = (idx % 4) * 70 + 'ms';
      io.observe(el);
    } else {
      el.classList.add('in');
    }
  });

  const so = ok ? new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      observer.unobserve(entry.target);
      const el = entry.target;
      const targetVal = +el.dataset.to;
      const suffix = el.dataset.sf || '';
      const t0 = performance.now();
      const step = t => {
        const progress = Math.min(1, (t - t0) / 1400);
        el.textContent = Math.round(targetVal * (1 - Math.pow(1 - progress, 3))) + suffix;
        if (progress < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    });
  }) : null;

  if (so) {
    app.querySelectorAll('.stat').forEach(el => {
      const match = el.textContent.trim().match(/^(\d+)(\+?)$/);
      if (!match) return;
      el.dataset.to = match[1];
      el.dataset.sf = match[2];
      el.textContent = '0' + match[2];
      so.observe(el);
    });
  }

  // Exact photo slot enhancer
  app.querySelectorAll('.ph').forEach(el => {
    if (el.dataset.d) return;
    el.dataset.d = '1';
    const t = el.textContent.trim();
    el.innerHTML = `<span>📷 <b>Photo slot</b>${t}<br><small>Upload JPG or WebP under 150 KB with alt text</small></span>`;
  });
}
